var categories={"common":"Most Used","hiring":"Hiring & Recruiting","onboarding":"Onboarding & Training","employee":"Employee Records","scheduling":"Scheduling & Labor","management":"Management & Shift Control","openclose":"Opening & Closing","cost":"Food Cost & Inventory","production":"Prep & Production","purchasing":"Purchasing & Receiving","guest":"Guest Service & Recovery","cleaning":"Cleaning & Sanitation","foodsafety":"Food Safety","equipment":"Equipment & Maintenance","cash":"Cash & Sales","safety":"Safety & Incidents","performance":"Performance & Corrective Action","planning":"Planning & Follow-Up","multi":"Multi-Location Controls","policies":"Policies & Pay"};
var docs={"application":{"name":"Job Application","icon":"A","tag":"Hiring intake","category":"hiring","common":true,"boundary":"Collect job-related information only. Keep background checks, I-9 verification, medical/accommodation records and interview scoring in separate controlled processes.","fields":[["position","Position(s) applied for","text","Server, Cook, Dishwasher, Manager"],["start","Available start date","text",""],["workauth","Work authorization question","select",["Include: legally authorized to work in the U.S.","Omit from application"]],["references","Job-related references","select",["Include two references","Omit references"]]],"sections":[["Applicant Information","Name, phone, email, address and preferred contact method.",""],["Position & Availability","Position sought, days/times available, desired hours, earliest start date and scheduling limitations the applicant chooses to disclose.",""],["Restaurant Experience & Skills","Restaurant roles held, equipment or stations learned, certifications if job-related, and relevant skills.",""],["Work History","Recent employers, role, dates, primary duties and reason for leaving.",""],["Job-Related Questions","Ability to meet the stated schedule and essential job requirements with or without reasonable accommodation.","review"],["Applicant Acknowledgment","Applicant certifies that the information provided is accurate and understands that an application is not a promise of employment.","review"]]},"jobdesc":{"name":"Job Description","icon":"J","tag":"Role clarity","category":"hiring","common":true,"boundary":"Describe the job as it is actually performed. Review essential duties, physical requirements, wage/classification language and local requirements before use.","fields":[["role","Job title","text","Server"],["reports","Reports to","text","Restaurant Manager"],["schedule","Typical schedule","text","Variable shifts including nights/weekends"],["success","Primary success measure","text",""]],"sections":[["Position Purpose","Why this position exists and what result the role is responsible for.",""],["Essential Responsibilities","The core duties that must be performed consistently.",""],["Service / Production Standards","Restaurant-specific quality, speed, sanitation, teamwork and guest-service expectations.",""],["Knowledge & Skills","Job-related experience, training, certifications or abilities.",""],["Physical / Work Environment","Job-related physical and environmental requirements stated objectively.","review"],["Schedule & Attendance","Expected availability, punctuality, shift handoff and attendance requirements.",""],["Performance Measures","How the restaurant will evaluate readiness and ongoing performance.",""],["Acknowledgment","Employee and manager acknowledge receipt and discussion of the job description.",""]]},"interview":{"name":"Interview Evaluation & Scorecard","icon":"I","tag":"Consistent interviews","category":"hiring","common":true,"boundary":"Use the same job-related core criteria for candidates applying to the same role. Do not score protected characteristics, medical information or unrelated personal circumstances.","fields":[["candidate","Candidate name","text",""],["role","Position","text",""],["interviewer","Interviewer","text",""],["date","Interview date","text",""]],"sections":[["Minimum Requirements","Confirm the candidate meets the stated job-related minimum requirements.",""],["Availability Fit","Compare stated availability with the role\u2019s actual scheduling requirements.",""],["Experience & Learning","Relevant experience, examples of learning new tasks and ability to explain prior responsibilities.",""],["Service / Team Scenarios","Use consistent restaurant scenarios to evaluate judgment, communication and care.",""],["Role-Specific Questions","Questions tied directly to the position\u2019s essential responsibilities.",""],["Evidence Notes","Record concrete examples and answers rather than impressions or labels.",""],["Overall Job-Related Assessment","Summarize strengths, concerns and follow-up questions using the same criteria used for other candidates.","review"],["Next Step","Advance, hold for additional review, or close the application. Final decision remains with the authorized hiring manager.","review"]]},"reference":{"name":"Reference Check Record","icon":"R","tag":"Reference notes","category":"hiring","common":false,"boundary":"Ask only job-related questions and apply the same reference-check practice consistently. State laws and company policy may limit what may be requested or disclosed.","fields":[["candidate","Candidate","text",""],["reference","Reference name","text",""],["relationship","Professional relationship","text",""],["checker","Checked by","text",""]],"sections":[["Identity & Relationship","Confirm who the reference is and how they worked with the candidate.",""],["Employment / Role Confirmation","Record only information the reference is willing and permitted to confirm.",""],["Job-Related Strengths","Ask about work quality, reliability, teamwork or other criteria relevant to the position.",""],["Development Areas","Ask for job-related development areas without seeking protected or medical information.",""],["Rehire / Recommendation Question","If permitted, record whether the reference would work with the candidate again and any job-related explanation.",""],["Reference Notes","Document factual statements and identify the speaker; do not convert unverified claims into facts.","review"]]},"offer":{"name":"Offer & Employment Terms Letter","icon":"O","tag":"Offer details","category":"hiring","common":false,"boundary":"Offer language can create legal obligations. Verify wage, classification, at-will/contract language, contingencies and state/local notice requirements before issue.","fields":[["candidate","Candidate","text",""],["role","Position","text",""],["rate","Starting pay / rate","text",""],["start","Proposed start date","text",""]],"sections":[["Offer","State the position and that the restaurant is extending an offer subject to any lawful conditions listed.",""],["Compensation","State the pay basis and applicable tip/bonus structure without promising amounts not guaranteed.","review"],["Schedule / Classification","State expected schedule, full-/part-time status and exempt/nonexempt classification only after review.","review"],["Conditions","List lawful conditions such as completion of required onboarding, permits or authorized screening processes.",""],["Policies & Benefits","Reference the handbook, benefits eligibility or meal/uniform practices without creating unintended guarantees.","review"],["Acceptance","Candidate acceptance, signature, date and deadline for return.",""]]},"selection":{"name":"Hiring Decision Record","icon":"D","tag":"Selection rationale","category":"hiring","common":false,"boundary":"Document job-related selection criteria and evidence. Do not record protected characteristics, medical details or speculative personality labels.","fields":[["candidate","Candidate","text",""],["role","Position","text",""],["decision","Decision","select",["Selected","Alternate / hold","Not selected"]],["manager","Authorized hiring manager","text",""]],"sections":[["Criteria Used","List the job-related criteria used for all candidates considered for this opening.",""],["Evidence Considered","Application, interview examples, skills checks, lawful reference information and role requirements.",""],["Selection Rationale","Explain the decision using documented job-related evidence.","review"],["Consistency Check","Confirm the same core criteria were applied to similarly situated candidates.",""],["Approval","Authorized manager review, date and next action.",""]]},"handbook":{"name":"Employee Handbook","icon":"H","tag":"Policies & expectations","category":"onboarding","common":true,"boundary":"A handbook is a customizable framework, not legal advice. State, local, company, union, licensing and industry requirements may require different language or additional policies.","fields":[["effective","Effective date","text",""],["reviewer","Approved / reviewed by","text","Owner / Authorized HR Reviewer"],["paycycle","Pay schedule reference","text",""],["contact2","Employee questions contact","text",""]],"sections":[["Welcome & Purpose","Welcome to the restaurant, how to use the handbook, and where employees should ask questions.",""],["Employment Relationship & Changes","Describe the restaurant\u2019s employment relationship and policy-change process only after qualified review.","review"],["Equal Employment & Respect","Equal opportunity, anti-harassment, reporting options, anti-retaliation and respectful workplace expectations.","review"],["Attendance & Scheduling","Call-off procedure, punctuality, schedule posting, shift changes and no-call/no-show expectations.",""],["Pay, Timekeeping & Tips","Timekeeping, pay schedule, tip practices, overtime approval and deduction questions.","review"],["Appearance, Uniform & Personal Items","Uniform, grooming, phones, bags, personal property and hygiene expectations.",""],["Food Safety & Workplace Safety","Employee health reporting, handwashing, allergen awareness, injury reporting and safety expectations.",""],["Conduct & Guest Care","Guest treatment, teamwork, conflicts, dishonesty, violence, substances and professional conduct.",""],["Coaching & Corrective Action","How coaching, documentation, investigation and corrective action are generally handled.","review"],["Leave & Accommodation Processes","Where employees request protected leave or workplace accommodation without placing private medical details in general files.","review"],["Technology, Social Media & Confidentiality","Restaurant systems, guest information, business records, social media and confidentiality expectations.",""],["Acknowledgment","Employee acknowledges receipt, opportunity to ask questions and responsibility to follow current policies.",""]]},"onboarding":{"name":"New Hire / Onboarding Packet","icon":"N","tag":"First days","category":"onboarding","common":true,"boundary":"Use current government forms from the responsible authority. This builder organizes restaurant-specific onboarding and does not recreate official tax or work-authorization forms.","fields":[["role","Position","text",""],["manager","Primary manager","text",""],["trainer","Trainer","text",""],["firstshift","First shift","text",""]],"sections":[["New Hire Checklist","Offer/role confirmation, payroll routing, emergency contact, handbook issue, uniform, schedule and training assignments.",""],["Employee & Position Information","Employee contact information, position, department, manager, trainer, hire date and first shift.",""],["First-Shift Readiness","Arrival location, uniform, parking, clock-in, meal/break process, trainer and opening expectations.",""],["Required Policies Issued","Handbook, safety, food safety, allergen, alcohol-service and location-specific policies as applicable.",""],["Training Plan","First station, assigned SOPs, trainer sign-offs, observation dates and follow-up.",""],["7-Day Check-In","Fit, questions, schedule, training gaps and manager follow-up.",""],["30-Day Retention Conversation","What is working, what is unclear, support needed and next development step.",""],["Employee Acknowledgments","List only the restaurant policies/documents actually provided to the employee.","review"]]},"emergency":{"name":"Emergency Contact Form","icon":"E","tag":"Emergency contact","category":"onboarding","common":false,"boundary":"Collect only information needed to contact a person in an emergency. Store it with restricted access and do not use it for employment decisions.","fields":[["employee","Employee","text",""],["role","Position","text",""],["effective","Effective date","text",""],["manager","Received by","text",""]],"sections":[["Employee Contact Information","Current phone, personal email and mailing address if needed for business records.",""],["Primary Emergency Contact","Name, relationship, primary phone and alternate phone.",""],["Secondary Emergency Contact","Optional second contact.",""],["Update Responsibility","Employee agrees to update the restaurant when emergency-contact information changes.",""],["Privacy / Access","State who may access the form and that it is for emergency/administrative use only.","review"]]},"property":{"name":"Uniform / Keys / Property Issue & Return","icon":"K","tag":"Issued property","category":"onboarding","common":false,"boundary":"Document company property without creating unauthorized payroll deductions. Wage-deduction rules vary by jurisdiction and should be reviewed separately.","fields":[["employee","Employee","text",""],["role","Position","text",""],["issued","Issue date","text",""],["manager","Issued by","text",""]],"sections":[["Items Issued","Uniform pieces, keys, access cards, devices, tools or other company property.",""],["Condition / Identification","Quantity, size, serial/key number and condition when issued.",""],["Use & Care Expectations","Reasonable care, security, return and loss-reporting expectations.",""],["Return Record","Date returned, condition and manager verification.",""],["Unreturned / Damaged Property","Record facts and route any deduction/recovery decision for authorized review rather than assuming a payroll deduction is allowed.","review"],["Signatures","Employee and issuing/receiving manager signatures and dates.",""]]},"trainingplan":{"name":"Training Plan & Station Sign-Off","icon":"T","tag":"Role mastery","category":"onboarding","common":true,"boundary":"Training sign-off should show what was taught and verified. It does not replace legally required licenses, certifications or safety training records.","fields":[["employee","Employee","text",""],["role","Position","text",""],["trainer","Trainer","text",""],["target","Target completion date","text",""]],"sections":[["Training Path","List orientation, station sequence, shadow shifts, supervised practice and independent verification.",""],["Required SOPs","Identify the SOPs and standards the employee must learn for the role.",""],["Knowledge / Skills Checks","Menu, POS, food safety, recipes, service steps, equipment or role-specific checks.",""],["Trainer Sign-Off","Trainer records demonstration date, coached practice and independent performance date.",""],["Employee Questions / Gaps","Record topics requiring additional explanation or practice.",""],["Readiness Decision","Ready for independent assignment, ready with restrictions, or additional training required.","review"],["Follow-Up","Next review date and manager/trainer responsible.",""]]},"development90":{"name":"30 / 60 / 90-Day New Hire Plan","icon":"90","tag":"Retention & growth","category":"onboarding","common":false,"boundary":"Use observable job expectations and development goals. The plan should support learning and retention, not create an automatic termination rule.","fields":[["employee","Employee","text",""],["role","Position","text",""],["hiredate","Hire date","text",""],["manager","Manager","text",""]],"sections":[["First 30 Days","Orientation, core standards, basic station competence, attendance and questions to resolve.",""],["Days 31\u201360","Increasing independence, cross-training, guest/team contribution and remaining skill gaps.",""],["Days 61\u201390","Consistent role performance, advanced skills, reliability and readiness for broader responsibilities.",""],["Employee Goals","Goals the employee wants to accomplish during the first 90 days.",""],["Manager Support","Training, coaching, tools or scheduling support the manager will provide.",""],["30-Day Check-In","Progress, support needed and next priorities.",""],["60-Day Check-In","Progress, remaining gaps and next priorities.",""],["90-Day Review","Readiness, retention conversation, development next step and future check-in date.","review"]]},"certification":{"name":"Certification & Permit Record","icon":"C","tag":"Credentials","category":"onboarding","common":false,"boundary":"Use this as an internal tracking record only. Verify each credential directly and follow the issuing authority\u2019s renewal and retention requirements.","fields":[["employee","Employee","text",""],["role","Position","text",""],["credential","Credential / permit type","text",""],["issuer","Issuing authority","text",""]],"sections":[["Credential Details","Credential name, number if appropriate, issue date and expiration date.",""],["Verification","Who verified the credential and where the source record is stored.",""],["Role Requirement","Why this credential is required or relevant to the employee\u2019s assignment.",""],["Renewal Reminder","Renewal lead time and responsible person.",""],["Status History","Active, pending renewal, expired or no longer required.",""]]},"availability":{"name":"Availability & Scheduling Agreement","icon":"S","tag":"Schedule expectations","category":"scheduling","common":true,"boundary":"Availability is not the weekly schedule. Capture the employee\u2019s recurring availability and the restaurant\u2019s process for requesting changes; review minor-work and predictive-scheduling requirements where applicable.","fields":[["role","Position","text",""],["effective","Effective date","text",""],["notice","Requested notice for changes","text","Example: 14 days"],["manager","Schedule manager","text",""]],"sections":[["Recurring Availability","For each day, record earliest available time, latest available time and unavailable status.",""],["Preferred Hours","Desired weekly hours and any voluntary preferences.",""],["Required Availability for Role","Restaurant\u2019s minimum availability expectations for this role, if any.",""],["Change Request Process","How employees request a permanent or temporary availability change.",""],["Schedule Posting & Review","Where schedules are posted and employee responsibility to review assigned shifts.",""],["Shift Swap / Coverage Process","How swaps, releases and manager approval work.",""],["Acknowledgment","Employee confirms the availability submitted is accurate as of the effective date.",""]]},"timeoff":{"name":"Time-Off Request","icon":"TO","tag":"Requested dates off","category":"scheduling","common":true,"boundary":"A request is not an approval. Record submitted, approved/denied/pending status and the manager decision separately from protected-leave or accommodation processes.","fields":[["employee","Employee","text",""],["role","Position","text",""],["dates","Requested date(s)","text",""],["status","Status","select",["Pending","Approved","Denied","Modified / discuss"]]],"sections":[["Request","Specific date(s), full day or time range and date submitted.",""],["Scheduling Notes","Optional operational notes; employees should not be required to disclose private medical details on a general time-off form.","review"],["Manager Review","Coverage considerations, decision date and authorized manager.",""],["Decision","Approved, denied, modified or needs discussion; include the approved date/time range.",""],["Employee Notification","How and when the employee was informed of the decision.",""]]},"availabilitychange":{"name":"Availability Change Request","icon":"AC","tag":"Recurring availability","category":"scheduling","common":false,"boundary":"Use this for recurring availability changes, not one-time days off. Apply the restaurant\u2019s notice process consistently and review local scheduling requirements where applicable.","fields":[["employee","Employee","text",""],["role","Position","text",""],["effective","Requested effective date","text",""],["status","Status","select",["Pending","Approved","Denied","Modified / discuss"]]],"sections":[["Current Availability","Record the current recurring availability being changed.",""],["Requested Availability","Record the proposed recurring days/times available and unavailable.",""],["Reason / Context","Optional employee context; do not require private medical information on this general form.","review"],["Operational Review","Role coverage, business needs and alternatives discussed.",""],["Decision & Effective Date","Approved, denied or modified availability and the date it becomes the active scheduling rule.",""],["Shift Lab Update","Confirm the employee profile was updated in Gravity Shift Lab if the restaurant uses it.",""]]},"shiftswap":{"name":"Shift Swap / Coverage Request","icon":"SW","tag":"Trade or cover shift","category":"scheduling","common":false,"boundary":"A swap is not final until the authorized manager approves it. Review overtime, qualifications, age/minor restrictions and role coverage before approval.","fields":[["employee","Original employee","text",""],["shift","Original shift","text",""],["replacement","Proposed replacement / swap partner","text",""],["status","Status","select",["Pending","Approved","Denied"]]],"sections":[["Original Assignment","Date, time, section/station and role.",""],["Proposed Coverage","Replacement employee or two-way swap details.",""],["Employee Agreement","Both employees confirm the proposed change if a swap is involved.",""],["Manager Checks","Availability, section qualification, overtime, closing/opening concerns and staffing coverage.",""],["Approval","Authorized manager decision and date.",""],["Schedule Update","Confirm the posted/digital schedule was updated after approval.",""]]},"calloff":{"name":"Call-Off / Attendance Record","icon":"CA","tag":"Attendance record","category":"scheduling","common":false,"boundary":"Record the communication and operational response. Keep medical details and protected-leave information out of general attendance files and route them to the appropriate confidential process.","fields":[["employee","Employee","text",""],["shift","Affected shift","text",""],["received","Call / message received","text",""],["manager","Manager receiving notice","text",""]],"sections":[["Notice Details","Date/time notice was received, communication method and who received it.",""],["Employee Statement","Record the employee\u2019s own words briefly; do not seek diagnosis or unnecessary medical information.","review"],["Coverage Action","Who covered the shift, whether the shift was modified, and any operational impact.",""],["Policy Check","Notice timing and attendance policy applied; identify possible protected-leave/accommodation issue for confidential review if raised.","review"],["Follow-Up","Manager follow-up needed, date and outcome.",""]]},"schedulechange":{"name":"Schedule Change / Manager Approval","icon":"SC","tag":"Schedule exception","category":"scheduling","common":false,"boundary":"Use this to document manager-approved schedule changes after posting. Review overtime, role qualifications and local scheduling notice requirements.","fields":[["employee","Employee","text",""],["original","Original shift","text",""],["revised","Revised shift","text",""],["manager","Approving manager","text",""]],"sections":[["Change Requested","Who requested the change, date/time, and what was requested.",""],["Reason / Operational Need","Brief job-related reason or operational need; do not require private information.",""],["Coverage & Labor Check","Coverage, qualifications, overtime and rest/open-close implications.",""],["Approval","Approved/denied, manager and date/time.",""],["Schedule Notification","Confirm affected employees and schedule systems were updated.",""]]},"policyack":{"name":"Policy & Acknowledgment Packet","icon":"P","tag":"Issue & sign","category":"policies","common":true,"boundary":"An acknowledgment proves receipt and discussion; it should not ask an employee to waive legal rights or agree to language broader than the policy actually issued.","fields":[["packet","Packet name","text","Core Restaurant Policies"],["effective","Effective date","text",""],["manager","Issuing manager","text",""],["version","Policy version","text","1.0"]],"sections":[["Policies Included","List the exact policy titles and versions included in this packet.",""],["Restaurant-Specific Standards","Add only the operational standards being issued with this packet.",""],["Employee Questions","Identify who can answer policy questions before signing.",""],["Acknowledgment of Receipt","Employee acknowledges receiving the listed policies and having an opportunity to ask questions.","review"],["Training / Explanation Record","Manager records any required explanation or training completed with the packet.",""],["Signatures","Employee, manager/trainer and date.",""]]},"tipack":{"name":"Tip Policy / Tip Pool Acknowledgment","icon":"TP","tag":"Tipped employees","category":"policies","common":false,"boundary":"Federal and state tip rules can differ. Verify current wage/tip-credit and tip-pool requirements before use; managers/supervisors may not receive employee tips except as law permits.","fields":[["role","Tipped role","text",""],["cashwage","Direct cash wage","text",""],["tipcredit","Tip credit claimed, if any","text",""],["pool","Required tip-pool contribution / method","text",""]],"sections":[["Tip Policy Overview","Explain how tips are received, recorded, distributed and retained.",""],["Tip Credit Notice","If a tip credit is used, state the required current notice information and verify it against applicable law before issue.","review"],["Tip Pool Participants","Identify eligible job classifications and the contribution/distribution method.",""],["Managers / Supervisors","State the restaurant\u2019s rule consistent with applicable law regarding manager/supervisor participation.","review"],["Reporting & Payroll","How employees report tips and where payroll questions should go.",""],["Employee Questions","Provide a contact before acknowledgment.",""],["Acknowledgment","Employee acknowledges receipt and explanation of the current tip policy; this does not waive legal rights.","review"]]},"cashhandling":{"name":"Cash Handling / Register Agreement","icon":"$","tag":"Cash & POS control","category":"policies","common":false,"boundary":"Set operational expectations without assuming automatic deductions for shortages. Wage-deduction and loss-recovery rules vary by jurisdiction.","fields":[["employee","Employee","text",""],["role","Position","text",""],["drawer","Drawer / register assignment","text",""],["manager","Manager","text",""]],"sections":[["Assigned Controls","Register login, drawer assignment, safe/drop rules and access limitations.",""],["Transaction Standards","Sales, comps, discounts, voids, refunds, gift cards and cash-change expectations.",""],["Count / Handoff","Opening count, shift handoff and closing count responsibilities.",""],["Shortage / Overages","How discrepancies are reported and investigated; do not state an automatic payroll deduction unless independently authorized and lawful.","review"],["Security","No sharing credentials, unattended cash rules and robbery/safety priorities.",""],["Acknowledgment","Employee acknowledges training and the current cash-handling standards.",""]]},"mealdiscount":{"name":"Employee Meal / Discount Policy","icon":"M","tag":"Meals & discounts","category":"policies","common":false,"boundary":"Customize to actual restaurant practice and verify any wage, tax or state meal/rest-break implications separately.","fields":[["eligibility","Eligible employees / shifts","text",""],["discount","Meal / discount amount","text",""],["timing","When benefit may be used","text",""],["approver","Manager approval rule","text",""]],"sections":[["Eligibility","Who qualifies and under what work conditions.",""],["Allowed Use","What menu items, amount/discount, timing and dine-in/takeout rules apply.",""],["Ring-In / Approval","How employee meals or discounts are entered in the POS and who approves them.",""],["Not Allowed","Sharing, stacking discounts, alcohol or other exclusions as applicable.",""],["Meal / Break Distinction","Clarify that the discount/meal benefit is separate from legally required break practices.","review"],["Acknowledgment","Employee acknowledges the current meal/discount rules.",""]]},"foodsafetyhealth":{"name":"Food Safety & Employee Health Acknowledgment","icon":"FS","tag":"Food safety reporting","category":"policies","common":false,"boundary":"Use local health-code requirements and approved employee-health guidance. Do not use this general acknowledgment to collect diagnoses or unrelated medical information.","fields":[["role","Position","text",""],["manager","Manager / trainer","text",""],["effective","Effective date","text",""],["version","Policy version","text",""]],"sections":[["Food Safety Duties","Handwashing, glove/utensil use, cross-contamination prevention, time/temperature and sanitation expectations relevant to the role.",""],["Employee Health Reporting","Explain when employees must notify management about symptoms/exposures required by applicable food-safety rules without asking for unrelated medical history.","review"],["Restriction / Exclusion Process","State that management will follow applicable health-code requirements for restriction/exclusion and return to food work.","review"],["Allergen / Cross-Contact","Restaurant allergen communication and escalation expectations.",""],["Training Confirmation","Topics reviewed, trainer and date.",""],["Acknowledgment","Employee acknowledges the food-safety and health-reporting expectations.",""]]},"alcoholservice":{"name":"Alcohol Service Responsibility Acknowledgment","icon":"21","tag":"Alcohol service","category":"policies","common":false,"boundary":"Alcohol-service rules are state/local specific. Use only where applicable and verify age, permit, service, refusal and training requirements for the restaurant\u2019s jurisdiction.","fields":[["employee","Employee","text",""],["role","Position","text",""],["permit","Permit / certification reference","text",""],["manager","Manager / trainer","text",""]],"sections":[["Service Eligibility","Required age, permit or certification for the employee\u2019s assigned duties.",""],["ID Verification","Restaurant ID-checking standard and escalation for questionable identification.",""],["Refusal of Service","When and how employees refuse or stop alcohol service and involve a manager.",""],["Intoxication / Safety","Restaurant procedure for signs of impairment, guest safety and manager intervention.",""],["No Unauthorized Service","No service outside restaurant policy or legal requirements.",""],["Training & Acknowledgment","Training completed, questions answered and employee acknowledgment.","review"]]},"coaching":{"name":"Coaching / Corrective Action Record","icon":"C","tag":"Fair follow-up","category":"performance","common":true,"boundary":"This record supports consistent coaching and documentation. It should capture facts, expectations and follow-up\u2014not automatically decide discipline or termination.","fields":[["employee","Employee","text",""],["role","Position","text",""],["manager","Manager / coach","text",""],["followup","Follow-up date","text",""]],"sections":[["Observed Facts","Describe what was observed or verified. Separate facts from assumptions or labels.",""],["Standard / Expectation","Identify the policy, SOP, job expectation or prior instruction involved.",""],["Employee Perspective","Record the employee\u2019s explanation or relevant context.",""],["Coaching Provided","What was explained, demonstrated or retrained.",""],["Required Correction","State the specific behavior or result required going forward.",""],["Support / Resources","Training, tools, schedule support or manager action needed.",""],["Follow-Up & Verification","Date, responsible manager and evidence that will verify improvement.",""],["Outcome / Next Step","Document the follow-up result and whether the matter is closed, continues in coaching, or needs authorized review.","review"]]},"review":{"name":"Performance Review & Development Plan","icon":"PR","tag":"Performance & growth","category":"performance","common":true,"boundary":"Use job-related standards and observable performance. Do not use protected characteristics, medical information or unrelated personal judgments in performance scoring.","fields":[["employee","Employee","text",""],["role","Position","text",""],["period","Review period","text",""],["reviewer","Reviewer","text",""]],"sections":[["Role Performance","Quality, accuracy, productivity and ability to perform the assigned role.",""],["Guest / Team Contribution","Guest care, communication, teamwork and shift support.",""],["Reliability & Readiness","Attendance, punctuality, preparation and follow-through.",""],["Safety & Standards","Food safety, workplace safety, SOP adherence and reporting.",""],["Strengths","Specific strengths supported by examples.",""],["Growth Priorities","One to three specific behaviors or skills to improve.",""],["Development Plan","Training, cross-training, coaching, resources and target dates.",""],["Goals & Follow-Up","Measurable next goals and scheduled follow-up date.",""],["Employee Comments","Employee may add comments or context.",""],["Signatures","Acknowledgment of review; signature does not have to mean agreement with every rating.","review"]]},"concern":{"name":"Employee Concern / Complaint Intake","icon":"EC","tag":"Raise concerns","category":"performance","common":false,"boundary":"Provide more than one reporting path where appropriate. Handle retaliation, harassment, discrimination, safety and other protected concerns under the restaurant\u2019s applicable procedures.","fields":[["employee","Employee / reporting person","text",""],["received","Date received","text",""],["recipient","Received by","text",""],["type","Concern type","select",["Workplace conduct","Scheduling / attendance","Pay / tip question","Safety","Harassment / discrimination concern","Other"]]],"sections":[["Concern in Employee\u2019s Words","Record the concern as reported, using the employee\u2019s words where practical.",""],["People / Events Involved","Who, what, when and where; avoid conclusions at intake.",""],["Immediate Safety / Retaliation Check","Identify whether immediate protection, alternate reporting or urgent escalation is needed.","review"],["Evidence / Witnesses","Documents, messages, video, witnesses or other information identified by the reporting person.",""],["Requested Resolution","What the employee is asking the restaurant to consider.",""],["Routing & Follow-Up","Who owns the follow-up, confidentiality limits and next contact date.","review"]]},"factfinding":{"name":"Manager Fact-Finding / Investigation Notes","icon":"FN","tag":"Fact record","category":"performance","common":false,"boundary":"This builder organizes factual notes; it does not make findings, determine credibility, or decide discipline. Sensitive matters may require HR or legal guidance and restricted files.","fields":[["matter","Matter / case reference","text",""],["manager","Fact-finder","text",""],["opened","Date opened","text",""],["status","Status","select",["Open","Pending information","Closed / routed"]]],"sections":[["Question to Resolve","Define the factual question being reviewed without assuming the answer.",""],["Sources Reviewed","Documents, schedules, POS records, video, policies, witnesses or other sources.",""],["Interview Notes","Who was interviewed, when, and factual notes attributed to the speaker.",""],["Timeline","Chronological events supported by available information.",""],["Conflicting Information","Identify contradictions or missing facts without guessing.",""],["Policy / SOP References","Relevant written standards; do not treat the policy reference as proof of what occurred.",""],["Next Step / Routing","Additional information needed or authorized person who will make the decision.","review"]]},"manageragreement":{"name":"Manager Expectations & Leadership Agreement","icon":"MG","tag":"Manager accountability","category":"performance","common":false,"boundary":"Clarify authority and expectations without creating guarantees beyond the restaurant\u2019s approved employment policies or organizational structure.","fields":[["manager","Manager","text",""],["role","Management role","text",""],["reports","Reports to","text",""],["effective","Effective date","text",""]],"sections":[["Leadership Purpose","What the manager is responsible for protecting: people, service, standards, truth and business controls.",""],["Shift Authority","Decisions the manager may make independently and decisions requiring escalation.",""],["Required Controls","Manager log, pre-shift planning, cash, labor, food safety, incident reporting and closing/opening controls as applicable.",""],["People Leadership","Fair scheduling, coaching, training, communication and anti-retaliation expectations.",""],["Handoff & Documentation","What must be documented before the manager leaves the shift.",""],["Measurement","Key operating and leadership measures used to evaluate the role.",""],["Acknowledgment","Manager and owner/GM acknowledge the authority, responsibilities and escalation paths.",""]]},"rolechange":{"name":"Promotion / Role / Pay Change Notice","icon":"UP","tag":"Change in role","category":"performance","common":false,"boundary":"Pay-rate, classification and written-notice requirements vary by jurisdiction. Verify the change before issue and keep payroll/HR systems synchronized.","fields":[["employee","Employee","text",""],["from","Current role","text",""],["to","New role","text",""],["effective","Effective date","text",""]],"sections":[["Change Summary","Promotion, transfer, demotion, temporary assignment or other approved change.",""],["Compensation / Classification","New rate or salary basis and classification only after authorized review.","review"],["Schedule / Reporting","New manager, department/station, expected schedule or location.",""],["New Responsibilities","Key responsibilities and standards that change with the role.",""],["Training / Transition","Required training, handoff and review dates.",""],["Approvals & Acknowledgment","Authorized approval, employee acknowledgment and payroll/system update confirmation.",""]]},"incident":{"name":"Incident / Near-Miss Report","icon":"!","tag":"Safety & incidents","category":"safety","common":true,"boundary":"Use this internal report to capture facts and immediate action. It does not replace OSHA Forms 300/300A/301 or required government/insurance reporting when those requirements apply.","fields":[["type","Incident type","select",["Employee injury / illness","Guest incident","Near miss","Property / equipment damage","Security / conduct incident","Other"]],["date","Date / time","text",""],["location2","Exact location","text",""],["manager","Manager completing report","text",""]],"sections":[["People Involved","Names/roles and contact information as appropriate.",""],["What Happened","Objective description of events; separate observation from statements made by others.",""],["Immediate Response","First aid, emergency services, area closure, product hold, manager/security action or other immediate response.",""],["Witnesses / Evidence","Witness names, photos, video, equipment, POS records or other evidence preserved.",""],["Hazard / Contributing Conditions","Floor, equipment, staffing, process, environment or other conditions observed; do not assign blame before review.",""],["Corrective Action","Immediate correction and longer-term prevention owner/date.",""],["External Reporting Check","Insurance, health department, OSHA or other reporting review as applicable.","review"],["Manager Follow-Up","Follow-up date, owner and closure status.",""]]},"separation":{"name":"Separation / Exit Checklist","icon":"X","tag":"End employment","category":"safety","common":false,"boundary":"Final-pay, benefits, notice and termination requirements vary by jurisdiction. This checklist organizes operational closeout and does not make the termination decision.","fields":[["employee","Employee","text",""],["role","Position","text",""],["lastday","Last day worked","text",""],["type","Separation type","select",["Voluntary resignation","Involuntary separation","Job abandonment / no return","Other"]]],"sections":[["Authorization / Documentation","Confirm the separation decision or resignation record is documented and authorized.",""],["Schedule & Access","Remove future shifts and disable POS, scheduling, keys, alarm, email or other access at the appropriate time.",""],["Company Property","Uniforms, keys, devices, cards, manuals and other property returned.",""],["Payroll / Final Pay Routing","Send final hours, tips, expenses and pay information to the authorized payroll process; verify applicable final-pay requirements.","review"],["Benefits / Notices","Route any required benefits or separation notices through the authorized process.","review"],["Records Retention","File the appropriate records with restricted access.",""],["Team / Operations Handoff","Reassign responsibilities and communicate only what the team needs to know.",""],["Closure","Manager verifies all applicable closeout items are complete.",""]]},"exitinterview":{"name":"Exit Interview","icon":"EI","tag":"Retention insight","category":"safety","common":false,"boundary":"Participation should be voluntary unless company policy states otherwise. Do not pressure the departing employee to waive rights or disclose protected/private information.","fields":[["employee","Employee","text",""],["role","Position","text",""],["lastday","Last day","text",""],["interviewer","Interviewer","text",""]],"sections":[["Reason for Leaving","Employee\u2019s stated reason in their own words.",""],["Role & Workload","What worked and what made the job difficult.",""],["Training & Management","Training quality, manager support, communication and fairness.",""],["Scheduling & Pay Practices","Scheduling experience, hours, tip/pay-process concerns and clarity of expectations.",""],["Team & Culture","Teamwork, respect, conflict and workplace concerns.",""],["What Would Have Helped Retention","Changes that might have improved the employee\u2019s experience or decision to stay.",""],["Rehire / Future Contact","Restaurant\u2019s authorized internal note and whether future contact is appropriate.",""],["Follow-Up Issues","Any concern requiring separate investigation, payroll review or safety/HR escalation.","review"]]},"resignation":{"name":"Resignation / Voluntary Separation Record","icon":"RS","tag":"Resignation record","category":"safety","common":false,"boundary":"Record the employee\u2019s voluntary notice and operational details. Do not rewrite the employee\u2019s reason or pressure the employee to sign statements they do not agree with.","fields":[["employee","Employee","text",""],["role","Position","text",""],["notice","Date notice received","text",""],["lastday","Stated final day","text",""]],"sections":[["Employee Notice","How resignation was communicated and the employee\u2019s stated final date.",""],["Employee-Stated Reason","Optional; use the employee\u2019s own words where provided.",""],["Notice / Schedule Plan","Shifts remaining, coverage plan and whether the employee expects to work the notice period.",""],["Property / Access","Items and access to return/disable.",""],["Final Pay Routing","Send final hours/tips/expenses to payroll and verify applicable final-pay rules.","review"],["Manager Confirmation","Manager acknowledges receipt and routes the separation checklist.",""]]},"returnwork":{"name":"Return-to-Work / Leave Administration Checklist","icon":"RT","tag":"Return after leave","category":"safety","common":false,"boundary":"Keep medical information confidential and separate. Use official FMLA/accommodation processes when applicable; this checklist only coordinates the operational return to work.","fields":[["employee","Employee","text",""],["role","Position","text",""],["return","Planned return date","text",""],["manager","Coordinating manager","text",""]],"sections":[["Protected Process Check","Confirm whether FMLA, disability accommodation, workers\u2019 compensation or another protected process applies and route to the authorized administrator.","review"],["Required Documentation Status","Record whether required documentation was received by the authorized administrator\u2014do not copy diagnosis details into this form.","review"],["Schedule / Assignment","Return date, scheduled shifts, temporary restrictions or approved accommodation instructions supplied to the manager.",""],["Access / Equipment","Restore needed system access, keys, uniform or equipment.",""],["Manager Briefing","Provide managers only the information needed to implement approved restrictions/accommodations.",""],["Follow-Up","Check-in date and administrator/manager responsible.",""]]}};

